package com.exito.chop;
import android.content.*;import android.graphics.*;import android.view.*;
/** Independent pad IN/OUT handles; pinch zoom and pan do not alter the source. */
final class WaveEditor extends View {
 final Engine e;final Paint p=new Paint(3);final ScaleGestureDetector scale;double left=0,right=1;short[] seen;int drag;float down,last;boolean moved;Runnable selected;
 int dp(float v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}WaveEditor(Context c){super(c);e=Engine.get(c);p.setTypeface(Typography.control(c));setBackgroundColor(SamplerView.PANEL);scale=new ScaleGestureDetector(c,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScaleBegin(ScaleGestureDetector d){e.freezeForEdit();drag=0;return true;}public boolean onScale(ScaleGestureDetector d){double at=left+d.getFocusX()/getWidth()*(right-left),range=Math.max(32./Math.max(32,e.source==null?32:e.source.length/2),Math.min(1,(right-left)/d.getScaleFactor()));left=Math.max(0,Math.min(1-range,at-range*d.getFocusX()/getWidth()));right=left+range;moved=true;invalidate();return true;}});}
 void zoom(double amount){double center=(left+right)/2,range=Math.max(32./Math.max(32,e.source==null?32:e.source.length/2),Math.min(1,(right-left)/amount));left=Math.max(0,Math.min(1-range,center-range/2));right=left+range;invalidate();}void all(){left=0;right=1;invalidate();}void selected(){if(e.source==null||!e.hasPad(e.selected))return;double n=e.source.length/2.;left=Math.max(0,e.start(e.selected)/n-.005);right=Math.min(1,e.end(e.selected)/n+.005);invalidate();}
 float x(int frame){return(float)((frame/(e.source.length/2.)-left)/(right-left)*getWidth());}int frame(float x){return(int)Math.max(0,Math.min(e.source.length/2-1,(left+x/getWidth()*(right-left))*e.source.length/2));}
 @Override protected void onDraw(Canvas c){super.onDraw(c);if(e.livePadTake!=null){p.setColor(SamplerView.BLUE);p.setStrokeWidth(dp(1));float[] peaks=e.waveform;for(int i=0;i<getWidth();i+=2){float amplitude=peaks[Math.min(peaks.length-1,i*peaks.length/Math.max(1,getWidth()))]*getHeight()*.4f;c.drawLine(i,getHeight()/2-amplitude,i,getHeight()/2+amplitude,p);}p.setColor(SamplerView.LIME);p.setTextSize(dp(10));c.drawText("DIRECTO · "+e.padCount()+" pads · toca el siguiente MARCAR",dp(7),getHeight()-dp(5),p);return;}if(e.source==null||e.liveMode&&!e.liveReady){p.setColor(SamplerView.MUTED);p.setTextSize(dp(11));c.drawText("Esperando audio real",dp(9),getHeight()/2,p);return;}if(seen!=e.source){seen=e.source;if(!e.capturing){left=0;right=1;}}float h=getHeight(),w=getWidth();int a=e.start(e.selected),b=e.end(e.selected);p.setColor(0x4430a5c9);if(e.hasPad(e.selected))c.drawRect(x(a),0,x(b),h,p);p.setColor(SamplerView.BLUE);p.setStrokeWidth(dp(1));float[] peaks=e.waveform;for(int i=0;i<w;i+=2){int at=Math.max(0,Math.min(peaks.length-1,(int)((left+i/w*(right-left))*peaks.length)));float amp=peaks[at]*h*.4f;c.drawLine(i,h/2-amp,i,h/2+amp,p);}p.setColor(0x667f66a0);if(e.padCount()>0)for(int cut:e.cuts)c.drawLine(x(cut),0,x(cut),h,p);if(e.hasPad(e.selected)){p.setStrokeWidth(dp(3));p.setColor(SamplerView.LIME);c.drawLine(x(a),0,x(a),h,p);p.setColor(SamplerView.PINK);c.drawLine(x(b),0,x(b),h,p);}p.setTextSize(dp(9));p.setStrokeWidth(1);p.setColor(SamplerView.FG);c.drawText(e.hasPad(e.selected)?String.format(java.util.Locale.US,"IN %.4f   OUT %.4f   CHOP %02d",a/(double)e.rate,b/(double)e.rate,e.selected+1):"Sin chops: toca el primer pad MARCAR",dp(7),h-dp(5),p);double cursor=e.playhead();if(cursor>=left&&cursor<=right){p.setColor(SamplerView.LIME);c.drawLine((float)((cursor-left)/(right-left)*w),0,(float)((cursor-left)/(right-left)*w),h,p);}if(e.scratchMode){p.setColor(SamplerView.PINK);p.setTextSize(dp(11));c.drawText("● VINYL / SCRATCH",dp(7),dp(14),p);double sc=e.output.mixer.vinylPosition();if(sc>=left&&sc<=right){p.setStrokeWidth(dp(2));c.drawLine((float)((sc-left)/(right-left)*w),0,(float)((sc-left)/(right-left)*w),h,p);}}if(e.playing||e.output.mixer.vinylActive())postInvalidateDelayed(40);}
 @Override public boolean onTouchEvent(MotionEvent event){if(e.livePadTake!=null||e.source==null||e.busy)return true;if(e.scratchMode){switch(event.getActionMasked()){
 case MotionEvent.ACTION_DOWN:getParent().requestDisallowInterceptTouchEvent(true);e.beginScratch(frame(event.getX()));invalidate();return true;
 case MotionEvent.ACTION_MOVE:e.moveScratch(frame(event.getX()));invalidate();return true;
 case MotionEvent.ACTION_UP:case MotionEvent.ACTION_CANCEL:e.endScratch();getParent().requestDisallowInterceptTouchEvent(false);performClick();invalidate();return true;
 }return true;}
 scale.onTouchEvent(event);if(event.getPointerCount()>1){getParent().requestDisallowInterceptTouchEvent(true);return true;}switch(event.getActionMasked()){case MotionEvent.ACTION_DOWN:down=last=event.getX();moved=false;getParent().requestDisallowInterceptTouchEvent(true);float a=Math.abs(x(e.start(e.selected))-down),b=Math.abs(x(e.end(e.selected))-down);drag=e.hasPad(e.selected)&&Math.min(a,b)<dp(21)?(a<b?1:2):0;if(drag>0){e.finishPadMarking(false);e.freezeForEdit();e.history.begin("Ajustar IN / OUT del chop");}return true;case MotionEvent.ACTION_MOVE:if(Math.abs(event.getX()-down)>dp(3))moved=true;if(drag>0){PadParams pad=e.padParams[e.selected];int f=frame(event.getX());if(drag==1)pad.start=Math.min(e.end(e.selected)-1,f);else pad.end=Math.max(e.start(e.selected)+1,Math.min(e.source.length/2,f));e.changed();}else if(moved&&right-left<.999){double delta=(last-event.getX())/getWidth()*(right-left),range=right-left;left=Math.max(0,Math.min(1-range,left+delta));right=left+range;invalidate();}last=event.getX();return true;case MotionEvent.ACTION_UP:case MotionEvent.ACTION_CANCEL:if(drag>0)e.history.end();else if(!moved&&event.getActionMasked()==MotionEvent.ACTION_UP){int f=frame(event.getX());for(int i=0;i<e.padCount();i++)if(f>=e.cuts[i]&&f<e.cuts[i+1]){e.select(i);if(selected!=null)selected.run();break;}}drag=0;getParent().requestDisallowInterceptTouchEvent(false);performClick();return true;}return true;}
 @Override public boolean performClick(){super.performClick();return true;}
}
